CREATE TABLE IF NOT EXISTS password_resets(token TEXT PRIMARY KEY,userId TEXT UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE,passwordStamp TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS email_preferences(userId TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,semester INTEGER NOT NULL REFERENCES semesters(id),notes INTEGER NOT NULL DEFAULT 0,notices INTEGER NOT NULL DEFAULT 0,events INTEGER NOT NULL DEFAULT 0,verified INTEGER NOT NULL DEFAULT 0,updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS email_verifications(token TEXT PRIMARY KEY,userId TEXT UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS email_outbox(id TEXT PRIMARY KEY,userId TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL,payload TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL,nextAttempt INTEGER NOT NULL,expires INTEGER NOT NULL,lease TEXT,leaseUntil INTEGER,state TEXT NOT NULL DEFAULT 'pending',lastCode TEXT);
CREATE TABLE IF NOT EXISTS email_budget(day TEXT PRIMARY KEY,total INTEGER NOT NULL,notifications INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS resets_expiry ON password_resets(expires);
CREATE INDEX IF NOT EXISTS verification_expiry ON email_verifications(expires);
CREATE INDEX IF NOT EXISTS outbox_due ON email_outbox(state,nextAttempt);
CREATE INDEX IF NOT EXISTS outbox_user ON email_outbox(userId);
